#!/usr/bin/env python3
import os, sys, re
from dataclasses import dataclass
from typing import List, Optional, Tuple, Union

VERSION = "tuc 1.3.0"

HELP_TEXT = """tuc 1.3.0
Cut text (or bytes) where a delimiter matches, then keep the desired parts.

USAGE:
    tuc [FLAGS] [OPTIONS] < input
    tuc [FLAGS] [OPTIONS] filepath

FLAGS:
    -g, --greedy-delimiter        Match consecutive delimiters as if it was one
    -p, --compress-delimiter      Print only the first delimiter of a sequence
    -s, --only-delimited          Print only lines containing the delimiter
    -V, --version                 Print version information
    -z, --zero-terminated         Line delimiter is NUL (\0), not LF (\n)
    -h, --help                    Print this help and exit
    -m, --complement              Invert fields (e.g. '2' becomes '1,3:')
    -j, --(no-)join               Print selected parts with delimiter in between
    --json                        Print fields as a JSON array of strings
    --no-mmap                     Disable memory mapping

OPTIONS:
    -f, --fields <bounds>         Fields to keep, 1-indexed, comma separated.
                                  Use colon (:) to match a range (inclusive).
                                  Use equal (=) to apply out of bound fallback.
                                  Fields can be negative (-1 is the last field).
                                  [default: 1:]

                                  e.g. cutting the string 'a-b-c-d' on '-'
                                    -f 1     => a
                                    -f 1:    => a-b-c-d
                                    -f 1:3   => a-b-c
                                    -f 3,2   => cb
                                    -f 3,1:2 => ca-b
                                    -f -3:-2 => b-c
                                    -f 1,8=fallback => afallback

                                  To re-apply the delimiter add -j, to replace
                                  it add -r (followed by the new delimiter).

                                  You can also format the output using {} syntax
                                  e.g.
                                    -f '({1}, {2})' => (a, b)

                                  You can escape { and } using {{ and }}.

    -b, --bytes <bounds>          Same as --fields, but it keeps bytes
    -c, --characters <bounds>     Same as --fields, but it keeps characters
    -l, --lines <bounds>          Same as --fields, but it keeps lines
                                  Implies --join. To merge lines, use --no-join
    -d, --delimiter <delimiter>   Delimiter used by --fields to cut the text
                                  [default: \t]
    -e, --regex <some regex>      Use a regular expression as delimiter
    -r, --replace-delimiter <new> Replace the delimiter with the provided text.
                                  Implies --join
    -t, --trim <type>             Trim the delimiter (greedy). Valid values are
                                  (l|L)eft, (r|R)ight, (b|B)oth
        --fallback-oob <fallback> Generic fallback output for any field that
                                  cannot be found (oob stands for out of bound).
                                  It's overridden by any fallback assigned to a
                                  specific field (see -f for help)
    -M, --fixed-memory <size>     Read the input in chunks of <size> kilobytes.
                                  This allows to read lines arbitrarily large.
                                  Works only with single-byte delimiters,
                                  fields in ascending order, -z, -j, -r

Options precedence:
    --trim and --compress-delimiter are applied before --fields or similar

Memory consumption:
    --characters and --fields read and allocate memory one line at a time

    --lines allocate memory one line at a time as long as the requested fields
    are ordered and non-negative (e.g. -l 1,3:4,4,7), otherwise it allocates
    the whole input in memory (it also happens when -p or -m are being used)

    --bytes allocate the whole input in memory

    --fixed-memory will read the input in chunks of <size> kilobytes. This
    allows to read lines arbitrarily large. Works only with single-byte
    delimiters, fields in ascending order, -z, -j, -r

Colors:
    Help is displayed using colors. Colors will be suppressed in the
    following circumstances:
    - when the TERM environment variable is not set or set to "dumb"
    - when the NO_COLOR environment variable is set (regardless of value)
"""

INTRO_TEXT = """tuc 1.3.0 - Created by Riccardo Attilio Galli

Cut text (or bytes) where a delimiter matches, then keep the desired parts.

Some examples:

    $ echo "a/b/c" | tuc -d / -f 1,-1
    ac

    $ echo "a/b/c" | tuc -d / -f 2:
    b/c

    $ echo "hello.bak" | tuc -d . -f 'mv {1:} {1}'
    mv hello.bak hello

    $ printf "a\nb\nc\nd\ne" | tuc -l 2:-2
    b
    c
    d

Run `tuc --help` for more detailed information.
Send bug reports to: https://github.com/riquito/tuc/issues
"""


def b(s: str) -> bytes:
    return s.encode('utf-8', 'surrogateescape')


def eprint(msg: str):
    sys.stderr.write(msg)
    if not msg.endswith('\n'):
        sys.stderr.write('\n')


def runtime_error(msg: str) -> int:
    eprint(f"tuc: runtime error. {msg}")
    return 1


class ParseFailure(Exception):
    def __init__(self, original: str, msg: str):
        self.original = original
        self.msg = msg
        super().__init__(msg)


class RenderFailure(Exception):
    def __init__(self, msg: str, partial: bytes = b''):
        self.msg = msg
        self.partial = partial
        super().__init__(msg)


@dataclass
class Selector:
    start: Optional[int]
    end: Optional[int]
    is_range: bool
    fallback: Optional[bytes]
    original: str
    body: str


@dataclass
class BoundsSpec:
    selectors: List[Selector]
    is_format: bool = False
    tokens: Optional[List[Tuple[str, Union[bytes, List[Selector]]]]] = None
    has_literal: bool = False


@dataclass
class Seg:
    fields: List[bytes]
    delims: List[bytes]
    original: bytes
    empty_record: bool = False
    regex: Optional[re.Pattern] = None
    delimiter: bytes = b'\t'
    compress: bool = False
    greedy: bool = False
    normal_string_split: bool = True


@dataclass
class Opts:
    greedy: bool = False
    compress: bool = False
    only_delimited: bool = False
    version: bool = False
    help: bool = False
    zero: bool = False
    complement: bool = False
    join: bool = False
    no_join: bool = False
    json: bool = False
    no_mmap: bool = False
    fields_bound: Optional[str] = None
    bytes_bound: Optional[str] = None
    chars_bound: Optional[str] = None
    lines_bound: Optional[str] = None
    delimiter: bytes = b'\t'
    delimiter_given: bool = False
    regex: Optional[str] = None
    replace: Optional[bytes] = None
    trim: Optional[str] = None
    fallback_oob: Optional[bytes] = None
    fixed_memory: Optional[int] = None
    filepath: Optional[str] = None
    unexpected: List[str] = None

    def __post_init__(self):
        if self.unexpected is None:
            self.unexpected = []


def parse_int(text: str, whole: str) -> int:
    if text in ('0', '-0'):
        raise ParseFailure(whole, 'Zero is not a valid field')
    try:
        # reject whitespace, +, and other non-rust-like forms by round-trip-ish checks
        if text == '' or text.strip() != text:
            raise ValueError
        if text.startswith('+'):
            raise ValueError
        val = int(text, 10)
    except ValueError:
        raise ParseFailure(whole, f"Not a number `{text}`")
    if val == 0:
        raise ParseFailure(whole, 'Zero is not a valid field')
    return val


def parse_selector(part: str, whole_for_error: Optional[str] = None) -> Selector:
    original = part if whole_for_error is None else whole_for_error
    if '=' in part:
        body, fb = part.split('=', 1)
        fallback = b(fb)
    else:
        body, fallback = part, None
    if ':' in body:
        left, right = body.split(':', 1)
        if left == '' and right == '':
            raise ParseFailure(original, 'Field format error, no numbers next to `:`')
        start = parse_int(left, original) if left != '' else None
        end = parse_int(right, original) if right != '' else None
        # Parse-time error when both explicit bounds are ordered impossibly in the text domain.
        if start is not None and end is not None:
            if (start > 0 and end > 0 and start > end) or (start < 0 and end < 0 and start > end):
                raise ParseFailure(original, 'Field left value cannot be greater than right value')
        return Selector(start, end, True, fallback, original, body)
    else:
        if body == '':
            # Observed: =fallback behaves like field 1 with a fallback.
            start = 1
        else:
            start = parse_int(body, original)
        return Selector(start, None, False, fallback, original, body)


def parse_selector_list(text: str) -> List[Selector]:
    if text == '':
        raise ParseFailure(text, 'UserBoundsList must contain at least one UserBounds')
    parts = text.split(',')
    sels: List[Selector] = []
    for p in parts:
        if p == '':
            raise ParseFailure(text, 'Field format error: empty field')
        sels.append(parse_selector(p, text))
    return sels


def parse_bounds(text: str) -> BoundsSpec:
    if '{' not in text and '}' not in text:
        return BoundsSpec(parse_selector_list(text), False, None, False)
    tokens: List[Tuple[str, Union[bytes, List[Selector]]]] = []
    i = 0
    lit = bytearray()
    placeholders = 0
    has_literal = False
    while i < len(text):
        ch = text[i]
        if ch == '{':
            if i + 1 < len(text) and text[i+1] == '{':
                lit.extend(b'{')
                has_literal = True
                i += 2
                continue
            if lit:
                tokens.append(('lit', bytes(lit)))
                lit.clear()
            j = text.find('}', i+1)
            if j == -1:
                raise ParseFailure(text, 'Field format error: missing closing parenthesis')
            inside = text[i+1:j]
            if inside == '':
                raise ParseFailure(text, 'Field format error: empty field')
            sels = parse_selector_list(inside)
            tokens.append(('sel', sels))
            placeholders += 1
            i = j + 1
        elif ch == '}':
            if i + 1 < len(text) and text[i+1] == '}':
                lit.extend(b'}')
                has_literal = True
                i += 2
                continue
            raise ParseFailure(text, 'Field format error: missing opening parenthesis')
        else:
            lit.extend(b(ch))
            has_literal = True
            i += 1
    if lit:
        tokens.append(('lit', bytes(lit)))
    if placeholders == 0:
        # The reference panics here. A parse-style error is friendlier and sufficient for normal use.
        raise ParseFailure(text, 'UserBoundsList must contain at least one UserBounds')
    selectors: List[Selector] = []
    for typ, val in tokens:
        if typ == 'sel':
            selectors.extend(val)  # type: ignore[arg-type]
    return BoundsSpec(selectors, True, tokens, has_literal)


def split_records(data: bytes, sep: bytes) -> List[bytes]:
    if data == b'':
        return []
    if sep == b'':
        return [data]
    parts = data.split(sep)
    if parts and parts[-1] == b'':
        parts = parts[:-1]
    return parts


def trim_string_record(rec: bytes, delim: bytes, trim: Optional[str], regex: Optional[re.Pattern]) -> bytes:
    if not trim:
        return rec
    left = trim in ('l', 'L', 'b', 'B')
    right = trim in ('r', 'R', 'b', 'B')
    out = rec
    if regex is not None:
        if left:
            while out:
                m = regex.match(out)
                if not m or m.end() == m.start():
                    break
                out = out[m.end():]
        if right:
            # Remove a run of regex matches at the end. Repeatedly finding all matches is slow but OK here.
            changed = True
            while out and changed:
                changed = False
                last = None
                for m in regex.finditer(out):
                    if m.end() == len(out) and m.end() > m.start():
                        last = m
                if last is not None:
                    out = out[:last.start()]
                    changed = True
    else:
        if delim == b'':
            return out
        if left:
            while out.startswith(delim):
                out = out[len(delim):]
        if right:
            while out.endswith(delim):
                out = out[:-len(delim)]
    return out


def find_string_delims(rec: bytes, delim: bytes, greedy: bool, compress: bool) -> Tuple[List[bytes], List[bytes]]:
    if delim == b'':
        # Empty delimiter: split at UTF-8-ish character boundaries, with empty ends.
        chars = utf8_units(rec)
        return [b''] + chars + [b''], [b''] * (len(chars) + 1)
    fields: List[bytes] = []
    delims: List[bytes] = []
    pos = 0
    n = len(rec)
    group = greedy or compress
    while True:
        idx = rec.find(delim, pos)
        if idx < 0:
            fields.append(rec[pos:])
            break
        fields.append(rec[pos:idx])
        run_start = idx
        idx += len(delim)
        if group:
            while rec.startswith(delim, idx):
                idx += len(delim)
        seg = rec[run_start:idx]
        if compress:
            seg = delim
        delims.append(seg)
        pos = idx
    return fields, delims


def find_regex_delims(rec: bytes, regex: re.Pattern, greedy: bool, compress: bool) -> Tuple[List[bytes], List[bytes]]:
    fields: List[bytes] = []
    delims: List[bytes] = []
    pos = 0
    matches = [m for m in regex.finditer(rec) if m.end() > m.start()]
    if not matches:
        return [rec], []
    i = 0
    group = greedy or compress
    while i < len(matches):
        m = matches[i]
        if m.start() < pos:
            i += 1
            continue
        fields.append(rec[pos:m.start()])
        run_start = m.start(); run_end = m.end(); first = rec[m.start():m.end()]
        i += 1
        if group:
            while i < len(matches) and matches[i].start() == run_end:
                run_end = matches[i].end()
                i += 1
        seg = first if compress else rec[run_start:run_end]
        delims.append(seg)
        pos = run_end
    fields.append(rec[pos:])
    return fields, delims


def make_seg(rec: bytes, opts: Opts, regex_compiled: Optional[re.Pattern]) -> Seg:
    r = trim_string_record(rec, opts.delimiter, opts.trim, regex_compiled)
    if regex_compiled is not None:
        fields, delims = find_regex_delims(r, regex_compiled, opts.greedy, opts.compress)
        normal = False
    else:
        fields, delims = find_string_delims(r, opts.delimiter, opts.greedy, opts.compress)
        normal = (not opts.greedy and not opts.compress)
    return Seg(fields, delims, r, r == b'', regex_compiled, opts.delimiter, opts.compress, opts.greedy, normal)


def utf8_units(data: bytes) -> List[bytes]:
    units: List[bytes] = []
    i = 0
    while i < len(data):
        c = data[i]
        length = 1
        if 0xC2 <= c <= 0xDF and i+1 < len(data) and 0x80 <= data[i+1] <= 0xBF:
            length = 2
        elif 0xE0 <= c <= 0xEF and i+2 < len(data) and all(0x80 <= data[i+k] <= 0xBF for k in (1,2)):
            length = 3
        elif 0xF0 <= c <= 0xF4 and i+3 < len(data) and all(0x80 <= data[i+k] <= 0xBF for k in (1,2,3)):
            length = 4
        units.append(data[i:i+length])
        i += length
    return units


def make_char_seg(rec: bytes) -> Seg:
    units = utf8_units(rec)
    return Seg(units if units else [b''], [b''] * max(0, len(units)-1), rec, rec == b'', None, b'', False, False, True)


def effective_fallback(sel: Selector, opts: Opts) -> Optional[bytes]:
    return sel.fallback if sel.fallback is not None else opts.fallback_oob


def resolve_index(idx: int, n: int, empty_ok: bool) -> Optional[int]:
    if empty_ok:
        return 1
    if idx < 0:
        pos = n + idx + 1
    else:
        pos = idx
    if pos < 1 or pos > n:
        return None
    return pos


def selector_error_value(sel: Selector, which: str = 'start') -> str:
    if which == 'end' and sel.end is not None:
        return str(sel.end)
    if sel.start is not None:
        return str(sel.start)
    if sel.end is not None:
        return str(sel.end)
    return sel.original


def resolve_selector(sel: Selector, seg: Seg, opts: Opts, mode: str) -> Tuple[int, int]:
    n = len(seg.fields)
    if seg.empty_record:
        return (1, 1)
    if not sel.is_range:
        pos = resolve_index(sel.start or 1, n, False)
        if pos is None:
            raise RenderFailure(f"Error: Out of bounds: {sel.start}")
        return pos, pos
    start_raw = sel.start if sel.start is not None else 1
    end_raw = sel.end
    start = resolve_index(start_raw, n, False)
    if start is None:
        raise RenderFailure(f"Error: Out of bounds: {start_raw}")
    if end_raw is None:
        end = n
    else:
        if end_raw < 0:
            end = resolve_index(end_raw, n, False)
            if end is None:
                raise RenderFailure(f"Error: Out of bounds: {end_raw}")
        else:
            if end_raw > n:
                # Plain string field and byte modes clamp finite positive right bounds; other modes tend to error.
                if (mode in ('fields', 'bytes') and seg.regex is None and seg.normal_string_split) or mode == 'bytes':
                    end = n
                else:
                    raise RenderFailure(f"Error: Out of bounds: {end_raw}")
            else:
                end = end_raw
    if start > end:
        raise RenderFailure("Error: Field left value cannot be greater than right value")
    return start, end


def transform_delim(d: bytes, seg: Seg, opts: Opts) -> bytes:
    if opts.replace is None:
        return d
    if seg.regex is not None:
        try:
            return seg.regex.sub(opts.replace, d)
        except Exception:
            return opts.replace
    if seg.delimiter == b'':
        return opts.replace
    return d.replace(seg.delimiter, opts.replace)


def render_range(seg: Seg, start: int, end: int, opts: Opts) -> bytes:
    if seg.empty_record:
        return b''
    out = bytearray()
    for i in range(start, end + 1):
        out.extend(seg.fields[i-1])
        if i < end and i-1 < len(seg.delims):
            out.extend(transform_delim(seg.delims[i-1], seg, opts))
    return bytes(out)


def expand_complement(sel: Selector, seg: Seg, opts: Opts, mode: str) -> List[Tuple[int, int]]:
    if seg.empty_record:
        return [(1, 1)]
    start, end = resolve_selector(sel, seg, opts, mode)
    n = len(seg.fields)
    pieces: List[Tuple[int, int]] = []
    if start > 1:
        pieces.append((1, start-1))
    if end < n:
        pieces.append((end+1, n))
    if not pieces:
        raise RenderFailure("Error: the complement is empty")
    return pieces


def count_pieces(selectors: List[Selector], seg: Seg, opts: Opts, mode: str) -> int:
    if opts.complement and not seg.empty_record:
        total = 0
        for s in selectors:
            try:
                total += len(expand_complement(s, seg, opts, mode))
            except RenderFailure:
                total += 1
        return total
    return len(selectors)


def render_selectors(seg: Seg, selectors: List[Selector], opts: Opts, mode: str,
                     join_enabled: bool, trailing_more: int = 0) -> bytes:
    sep = opts.replace if opts.replace is not None else (seg.delimiter if mode == 'fields' else b'')
    out = bytearray()
    # Pre-expand complement for count and render; if OOB with fallback, complement intentionally follows reference only for common valid cases.
    pieces: List[Tuple[Selector, Tuple[int, int]]] = []
    if opts.complement and not seg.empty_record:
        for sel in selectors:
            fb = effective_fallback(sel, opts)
            try:
                comps = expand_complement(sel, seg, opts, mode)
            except RenderFailure as ex:
                if fb is not None and 'Out of bounds' in ex.msg:
                    # complement+fallback is buggy upstream; this is a practical fallback.
                    pieces.append((Selector(1, None, False, fb, sel.original, sel.body), (0, 0)))
                    continue
                raise RenderFailure(ex.msg, bytes(out))
            for p in comps:
                pieces.append((sel, p))
    else:
        for sel in selectors:
            pieces.append((sel, (-1, -1)))
    total = len(pieces) + trailing_more
    rendered_count = 0
    for sel, interval in pieces:
        fb = effective_fallback(sel, opts)
        try:
            if interval == (0, 0):
                piece = fb or b''
            elif interval != (-1, -1):
                piece = render_range(seg, interval[0], interval[1], opts)
            else:
                start, end = resolve_selector(sel, seg, opts, mode)
                piece = render_range(seg, start, end, opts)
        except RenderFailure as ex:
            if fb is not None:
                piece = fb
            else:
                raise RenderFailure(ex.msg, bytes(out))
        out.extend(piece)
        rendered_count += 1
        if join_enabled and rendered_count < total:
            out.extend(sep)
    return bytes(out)


def render_format(seg: Seg, spec: BoundsSpec, opts: Opts, mode: str, join_enabled: bool) -> bytes:
    assert spec.tokens is not None
    # Count top-level render pieces in placeholders; used to append a join delimiter before intervening literal text.
    remaining = 0
    for typ, val in spec.tokens:
        if typ == 'sel':
            remaining += count_pieces(val, seg, opts, mode)  # type: ignore[arg-type]
    out = bytearray()
    for typ, val in spec.tokens:
        if typ == 'lit':
            out.extend(val)  # type: ignore[arg-type]
        else:
            sels: List[Selector] = val  # type: ignore[assignment]
            this_count = count_pieces(sels, seg, opts, mode)
            remaining -= this_count
            try:
                out.extend(render_selectors(seg, sels, opts, mode, join_enabled, trailing_more=remaining))
            except RenderFailure as ex:
                raise RenderFailure(ex.msg, bytes(out) + ex.partial)
    return bytes(out)


def json_escape(raw: bytes) -> bytes:
    out = bytearray(b'"')
    for c in raw:
        if c == 0x22:
            out.extend(b'\\"')
        elif c == 0x5c:
            out.extend(b'\\\\')
        elif c == 0x08:
            out.extend(b'\\b')
        elif c == 0x09:
            out.extend(b'\\t')
        elif c == 0x0a:
            out.extend(b'\\n')
        elif c == 0x0c:
            out.extend(b'\\f')
        elif c == 0x0d:
            out.extend(b'\\r')
        elif c < 0x20:
            out.extend(("\\u%04x" % c).encode())
        else:
            out.append(c)
    out.extend(b'"')
    return bytes(out)


def iter_json_elements_for_selector(seg: Seg, sel: Selector, opts: Opts, mode: str) -> List[bytes]:
    fb = effective_fallback(sel, opts)
    try:
        if opts.complement and not seg.empty_record:
            intervals = expand_complement(sel, seg, opts, mode)
        else:
            intervals = [resolve_selector(sel, seg, opts, mode)]
    except RenderFailure:
        if fb is not None:
            return [fb]
        raise
    elems: List[bytes] = []
    if seg.empty_record:
        return []
    for start, end in intervals:
        for i in range(start, end + 1):
            elems.append(seg.fields[i-1])
    return elems


def render_json(seg: Seg, spec: BoundsSpec, opts: Opts, mode: str) -> bytes:
    if seg.empty_record:
        return b''
    selectors = spec.selectors
    out = bytearray(b'[')
    first = True
    for sel in selectors:
        # Original writes a comma before discovering a later selector is OOB.
        if not first:
            out.extend(b',')
        try:
            elems = iter_json_elements_for_selector(seg, sel, opts, mode)
        except RenderFailure as ex:
            raise RenderFailure(ex.msg, bytes(out))
        if not elems:
            # If a selector produces nothing, keep comma behavior close enough.
            continue
        for j, elem in enumerate(elems):
            if j > 0:
                out.extend(b',')
            out.extend(json_escape(elem))
        first = False
    out.extend(b']')
    return bytes(out)


def render_record(rec: bytes, opts: Opts, spec: BoundsSpec, mode: str, regex_compiled: Optional[re.Pattern]) -> bytes:
    if mode == 'characters':
        seg = make_char_seg(rec)
    else:
        seg = make_seg(rec, opts, regex_compiled)
    if opts.only_delimited and mode == 'fields':
        if len(seg.delims) == 0:
            raise RenderFailure('__SKIP__')
    if opts.json:
        return render_json(seg, spec, opts, mode)
    join_enabled = False
    if mode == 'fields':
        join_enabled = opts.join or (opts.replace is not None)
    elif mode == 'characters':
        join_enabled = (opts.replace is not None)
    if spec.is_format:
        return render_format(seg, spec, opts, mode, join_enabled)
    else:
        return render_selectors(seg, spec.selectors, opts, mode, join_enabled)


def render_bytes(data: bytes, spec: BoundsSpec, opts: Opts) -> bytes:
    if data == b'':
        return b''
    seg = Seg([bytes([x]) for x in data], [b''] * max(0, len(data)-1), data, False, None, b'', False, False, True)
    # Byte mode ignores fallbacks, joins, replacements, JSON unsupported.
    save_fb = opts.fallback_oob
    save_replace = opts.replace
    save_join = opts.join
    opts.fallback_oob = None; opts.replace = None; opts.join = False
    try:
        if spec.is_format:
            out = render_format(seg, spec, opts, 'bytes', False)
        else:
            out = render_selectors(seg, spec.selectors, opts, 'bytes', False)
    finally:
        opts.fallback_oob = save_fb; opts.replace = save_replace; opts.join = save_join
    return out


def render_lines(data: bytes, spec: BoundsSpec, opts: Opts, sep: bytes) -> bytes:
    lines = split_records(data, sep)
    n = len(lines)
    # A compact reproduction of the observed line-mode streaming behavior for common positive bounds.
    def line_error(msg: str, partial: bytes = b''):
        raise RenderFailure(msg, partial)
    def render_line_selector(sel: Selector, join_enabled: bool, more: bool) -> bytes:
        if n == 0:
            # Open-ended positive ranges print one delimiter; closed positive ranges error.
            if sel.is_range and sel.end is None and (sel.start is None or (sel.start or 1) > 0):
                return sep
            if sel.start is not None and sel.start < 0:
                return b''
            if sel.is_range:
                s = 1 if sel.start is None else sel.start
                e = sel.end
                if e is None:
                    return sep
                line_error(f"Error: Out of bounds: {s}:{e}")
            line_error(f"Error: Out of bounds: {sel.start or 1}")
        # Special upstream quirk: -1-ish all-lines cases.
        if (not sel.is_range and sel.start == -1) or (sel.is_range and ((sel.start in (None, 1, -1)) and (sel.end in (None, -1, 1)))):
            return sep.join(lines) + sep
        # Other negative bounds usually error.
        if (sel.start is not None and sel.start < 0) or (sel.end is not None and sel.end < 0):
            if sel.start is not None and sel.start > 1 and sel.end is not None and sel.end < 0:
                line_error(f"Error: Out of bounds: {sel.start}")
            if sel.end is not None and sel.end < -1:
                line_error(f"Error: Out of bounds: {sel.end}")
            line_error(f"Error: Out of bounds: {sel.start if sel.start is not None else sel.end}")
        if not sel.is_range:
            idx = sel.start or 1
            if idx < 1 or idx > n:
                line_error(f"Error: Out of bounds: {idx}")
            return lines[idx-1] + (sep if join_enabled or not more else b'')
        start = sel.start or 1
        end = sel.end
        if end is None:
            if start > n:
                return sep
            return sep.join(lines[start-1:]) + sep
        if start < 1 or start > n:
            line_error(f"Error: Out of bounds: {start}:{end}" if sel.start is not None and sel.end is not None else f"Error: Out of bounds: {start}")
        if end > n:
            partial = sep.join(lines[start-1:])
            line_error(f"Error: Out of bounds: {start}:{end}", partial)
        return sep.join(lines[start-1:end]) + sep
    if opts.json:
        # Not supported; validation catches this.
        return b''
    join_enabled = not opts.no_join
    if opts.complement:
        # Basic complement over line numbers.
        seg = Seg(lines if lines else [b''], [sep]*(max(0, n-1)), data, n == 0, None, sep, False, False, True)
        return render_selectors(seg, spec.selectors, opts, 'fields', join_enabled)
    out = bytearray()
    selectors = spec.selectors
    for idx, sel in enumerate(selectors):
        try:
            piece = render_line_selector(sel, join_enabled, idx < len(selectors)-1)
        except RenderFailure as ex:
            raise RenderFailure(ex.msg, bytes(out) + ex.partial)
        if not join_enabled and idx < len(selectors)-1:
            # Remove final separator between top-level pieces in --no-join mode.
            if piece.endswith(sep):
                piece = piece[:-len(sep)]
        out.extend(piece)
    if not join_enabled and selectors and not out.endswith(sep):
        out.extend(sep)
    return bytes(out)


def compile_regex(pattern: str) -> Union[re.Pattern, int, None]:
    try:
        # Work byte-wise; Python bytes regex covers common ASCII regex usage.
        return re.compile(b(pattern))
    except re.error as ex:
        # Recreate the visible Rust-regex style for the common malformed cases.
        sys.stderr.write("tuc: runtime error. The regular expression is malformed. regex parse error:\n")
        sys.stderr.write(f"    {pattern}\n")
        sys.stderr.write("    ^\n")
        msg = str(ex)
        if 'unterminated character set' in msg or 'missing ]' in msg:
            sys.stderr.write("error: unclosed character class\n")
        elif 'look-behind' in msg or 'lookahead' in msg or 'look-behind' in msg or 'look-around' in msg or pattern.startswith('(?='):
            sys.stderr.write("error: look-around, including look-ahead and look-behind, is not supported\n")
        else:
            sys.stderr.write(f"error: {msg}\n")
        return 1


def validate_fixed_memory(opts: Opts, mode: str, spec: BoundsSpec, regex_compiled: Optional[re.Pattern]) -> Optional[int]:
    if opts.fixed_memory is None:
        return None
    if opts.fixed_memory == 0:
        return runtime_error("--fixed-memory cannot be 0")
    if mode != 'fields' or regex_compiled is not None or opts.json or opts.complement:
        return runtime_error("StreamOpt supports solely forward fields, join and single-character delimiters")
    if len(opts.delimiter) != 1:
        return runtime_error("Delimiter must be 1 byte wide for FastOpt")
    # Forward bounds: positive, ordered, no duplicates/backtracking.
    last = 0
    try:
        for sel in spec.selectors:
            if sel.start is not None and sel.start < 0:
                return runtime_error("Bounds cannot be converted to ForwardBounds")
            if sel.end is not None and sel.end < 0:
                return runtime_error("Bounds cannot be converted to ForwardBounds")
            s = sel.start or 1
            if s <= last:
                return runtime_error("Bounds cannot be converted to ForwardBounds")
            last = sel.end or s
    except Exception:
        return runtime_error("Bounds cannot be converted to ForwardBounds")
    return None


def parse_args(argv: List[str]) -> Union[Opts, int]:
    opts = Opts()
    if not argv:
        sys.stdout.write(INTRO_TEXT)
        return 0
    i = 0
    seen_f = False
    def need_value(name: str) -> Optional[str]:
        nonlocal i
        if i + 1 >= len(argv):
            eprint(f"the '{name}' option doesn't have an associated value")
            return None
        i += 1
        return argv[i]
    while i < len(argv):
        arg = argv[i]
        if arg == '--help': opts.help = True
        elif arg == '--version': opts.version = True
        elif arg == '--greedy-delimiter': opts.greedy = True
        elif arg == '--compress-delimiter': opts.compress = True
        elif arg == '--only-delimited': opts.only_delimited = True
        elif arg == '--zero-terminated': opts.zero = True
        elif arg == '--complement': opts.complement = True
        elif arg == '--join': opts.join = True
        elif arg == '--no-join': opts.no_join = True
        elif arg == '--json': opts.json = True
        elif arg == '--no-mmap': opts.no_mmap = True
        elif arg.startswith('--fields='):
            if seen_f: opts.unexpected += ['--fields', arg.split('=',1)[1]]
            else: opts.fields_bound = arg.split('=',1)[1]; seen_f = True
        elif arg == '--fields':
            val = need_value('--fields')
            if val is None: return 1
            if seen_f: opts.unexpected += ['--fields', val]
            else: opts.fields_bound = val; seen_f = True
        elif arg.startswith('--bytes='): opts.bytes_bound = arg.split('=',1)[1]
        elif arg == '--bytes':
            val = need_value('--bytes');
            if val is None: return 1
            opts.bytes_bound = val
        elif arg.startswith('--characters='): opts.chars_bound = arg.split('=',1)[1]
        elif arg == '--characters':
            val = need_value('--characters');
            if val is None: return 1
            opts.chars_bound = val
        elif arg.startswith('--lines='): opts.lines_bound = arg.split('=',1)[1]
        elif arg == '--lines':
            val = need_value('--lines');
            if val is None: return 1
            opts.lines_bound = val
        elif arg.startswith('--delimiter='):
            opts.delimiter = b(arg.split('=',1)[1]); opts.delimiter_given = True
        elif arg == '--delimiter':
            val = need_value('--delimiter');
            if val is None: return 1
            opts.delimiter = b(val); opts.delimiter_given = True
        elif arg.startswith('--regex='): opts.regex = arg.split('=',1)[1]
        elif arg == '--regex':
            val = need_value('--regex');
            if val is None: return 1
            opts.regex = val
        elif arg.startswith('--replace-delimiter='):
            opts.replace = b(arg.split('=',1)[1])
        elif arg == '--replace-delimiter':
            val = need_value('--replace-delimiter');
            if val is None: return 1
            opts.replace = b(val)
        elif arg.startswith('--trim='): opts.trim = arg.split('=',1)[1]
        elif arg == '--trim':
            val = need_value('--trim');
            if val is None: return 1
            opts.trim = val
        elif arg.startswith('--fallback-oob='):
            opts.fallback_oob = b(arg.split('=',1)[1])
        elif arg == '--fallback-oob':
            val = need_value('--fallback-oob');
            if val is None: return 1
            opts.fallback_oob = b(val)
        elif arg.startswith('--fixed-memory='):
            val = arg.split('=',1)[1]
            try: opts.fixed_memory = int(val)
            except ValueError: eprint(f"failed to parse '{val}': invalid digit found in string"); return 1
        elif arg == '--fixed-memory':
            val = need_value('--fixed-memory');
            if val is None: return 1
            try: opts.fixed_memory = int(val)
            except ValueError: eprint(f"failed to parse '{val}': invalid digit found in string"); return 1
        elif arg.startswith('--'):
            opts.unexpected.append(arg)
        elif arg.startswith('-') and arg != '-':
            # short cluster or short option with attached value
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch in 'gpsVzmhj':
                    if ch == 'g': opts.greedy = True
                    elif ch == 'p': opts.compress = True
                    elif ch == 's': opts.only_delimited = True
                    elif ch == 'V': opts.version = True
                    elif ch == 'z': opts.zero = True
                    elif ch == 'm': opts.complement = True
                    elif ch == 'h': opts.help = True
                    elif ch == 'j': opts.join = True
                    j += 1
                    continue
                if ch in 'fbcldertM':
                    name = '-' + ch
                    val = arg[j+1:] if j+1 < len(arg) else None
                    if val is None or val == '':
                        if i + 1 >= len(argv):
                            eprint(f"the '{name}' option doesn't have an associated value")
                            return 1
                        i += 1
                        val = argv[i]
                    if ch == 'f':
                        if seen_f: opts.unexpected += ['-f', val]
                        else: opts.fields_bound = val; seen_f = True
                    elif ch == 'b': opts.bytes_bound = val
                    elif ch == 'c': opts.chars_bound = val
                    elif ch == 'l': opts.lines_bound = val
                    elif ch == 'd': opts.delimiter = b(val); opts.delimiter_given = True
                    elif ch == 'e': opts.regex = val
                    elif ch == 'r': opts.replace = b(val)
                    elif ch == 't': opts.trim = val
                    elif ch == 'M':
                        try: opts.fixed_memory = int(val)
                        except ValueError: eprint(f"failed to parse '{val}': invalid digit found in string"); return 1
                    break
                else:
                    opts.unexpected.append('-' + ch)
                    j += 1
        else:
            if opts.filepath is None:
                opts.filepath = arg
            else:
                opts.unexpected.append(arg)
        i += 1
    if opts.unexpected:
        eprint(f"tuc: unexpected arguments: {opts.unexpected}")
        eprint("Try 'tuc --help' for more information.")
        return 1
    return opts


def determine_mode(opts: Opts) -> Tuple[str, str]:
    if opts.fields_bound is not None:
        return 'fields', opts.fields_bound
    if opts.chars_bound is not None:
        return 'characters', opts.chars_bound
    if opts.bytes_bound is not None:
        return 'bytes', opts.bytes_bound
    if opts.lines_bound is not None:
        return 'lines', opts.lines_bound
    return 'fields', '1:'


def main(argv: List[str]) -> int:
    parsed = parse_args(argv)
    if isinstance(parsed, int):
        return parsed
    opts = parsed
    if opts.help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts.version:
        sys.stdout.write(VERSION + "\n")
        return 0
    if opts.join and opts.no_join:
        return runtime_error("It's not possible to use --join and --no-join simultaneously")
    if opts.replace is not None and opts.no_join:
        return runtime_error("You can't pass --no-join when using --replace, which implies --join")
    if opts.trim is not None and opts.trim not in ('l','L','r','R','b','B'):
        eprint(f"failed to parse '{opts.trim}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth")
        return 1
    mode, bound_text = determine_mode(opts)
    # regex validation and restrictions
    regex_compiled = None
    if opts.regex is not None:
        if opts.join and opts.replace is None:
            return runtime_error("Cannot use --regex and --join without --replace-delimiter")
        if opts.compress and opts.replace is None:
            return runtime_error("Cannot use --regex and --compress-delimiter without --replace-delimiter")
        cre = compile_regex(opts.regex)
        if isinstance(cre, int):
            return cre
        regex_compiled = cre
    if opts.json and opts.replace is not None:
        return runtime_error("The use of --replace with --json is not supported")
    if opts.json and mode not in ('fields', 'characters'):
        return runtime_error("--json support is available only for --fields and --characters")
    try:
        spec = parse_bounds(bound_text)
    except ParseFailure as ex:
        eprint(f"failed to parse '{ex.original}': {ex.msg}")
        return 1
    if opts.json and spec.is_format and spec.has_literal:
        return runtime_error("Cannot format fields when using --json")
    fm = validate_fixed_memory(opts, mode, spec, regex_compiled)
    if fm is not None:
        return fm
    # Read input.
    if opts.filepath is not None:
        if not os.path.exists(opts.filepath):
            return runtime_error(f"The file \"{opts.filepath}\" does not exist")
        if not os.path.isfile(opts.filepath):
            return runtime_error(f"The path \"{opts.filepath}\" is not a file")
        with open(opts.filepath, 'rb') as f:
            data = f.read()
    else:
        data = sys.stdin.buffer.read()
    sep = b'\0' if opts.zero else b'\n'
    out_stream = sys.stdout.buffer
    try:
        if mode == 'bytes':
            out_stream.write(render_bytes(data, spec, opts))
            return 0
        if mode == 'lines':
            out_stream.write(render_lines(data, spec, opts, sep))
            return 0
        records = split_records(data, sep)
        for rec in records:
            try:
                rendered = render_record(rec, opts, spec, mode, regex_compiled)
            except RenderFailure as ex:
                if ex.msg == '__SKIP__':
                    continue
                out_stream.write(ex.partial)
                out_stream.flush()
                eprint(ex.msg)
                return 1
            out_stream.write(rendered + sep)
        return 0
    except RenderFailure as ex:
        out_stream.write(ex.partial)
        out_stream.flush()
        eprint(ex.msg)
        return 1


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
